using EventLensAI.Application.Common;using EventLensAI.Application.DTOs.Storage;using EventLensAI.Application.Interfaces.Persistence;using EventLensAI.Domain.Entities;using EventLensAI.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace EventLensAI.Infrastructure.Repositories;
internal sealed class StorageRepository(EventLensDbContext db):IStorageRepository{public Task<Organization?>GetOrganizationAsync(Guid id,CancellationToken ct)=>db.Organizations.FirstOrDefaultAsync(x=>x.Id==id,ct);public Task<StorageUsage?>GetUsageAsync(Guid o,CancellationToken ct)=>db.StorageUsages.FirstOrDefaultAsync(x=>x.OrganizationId==o,ct);public Task AddUsageAsync(StorageUsage x,CancellationToken ct)=>db.StorageUsages.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<StorageCategory>>CategoriesAsync(CancellationToken ct)=>await db.StorageCategories.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(ct);public Task<StorageCategory?>CategoryAsync(Guid id,CancellationToken ct)=>db.StorageCategories.FirstOrDefaultAsync(x=>x.Id==id,ct);public async Task<PagedResult<StorageFile>>SearchAsync(StorageSearchRequest r,CancellationToken ct){var q=db.StorageFiles.IgnoreQueryFilters().AsNoTracking().Include(x=>x.Category).Include(x=>x.Uploader).Where(x=>x.OrganizationId==r.OrganizationId&&x.IsDeleted==r.Trash);if(r.FolderId.HasValue)q=q.Where(x=>x.FolderId==r.FolderId);if(r.CategoryId.HasValue)q=q.Where(x=>x.CategoryId==r.CategoryId);if(!string.IsNullOrWhiteSpace(r.Search))q=q.Where(x=>x.FileName.Contains(r.Search)||x.OriginalFileName.Contains(r.Search));if(!string.IsNullOrWhiteSpace(r.MimeType))q=q.Where(x=>x.MimeType.StartsWith(r.MimeType));if(r.UploaderId.HasValue)q=q.Where(x=>x.UploaderId==r.UploaderId);if(r.From.HasValue)q=q.Where(x=>x.CreatedAt>=r.From);if(r.To.HasValue)q=q.Where(x=>x.CreatedAt<=r.To);if(!string.IsNullOrWhiteSpace(r.Tag))q=q.Where(x=>db.FileTags.Any(t=>t.StorageFileId==x.Id&&t.Tag==r.Tag));var total=await q.CountAsync(ct);var rows=await q.OrderByDescending(x=>x.CreatedAt).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).ToListAsync(ct);return new(rows,r.Page,r.PageSize,total);}public Task<StorageFile?>FileAsync(Guid id,bool deleted,CancellationToken ct)=>deleted?db.StorageFiles.IgnoreQueryFilters().Include(x=>x.Category).Include(x=>x.Uploader).FirstOrDefaultAsync(x=>x.Id==id,ct):db.StorageFiles.Include(x=>x.Category).Include(x=>x.Uploader).FirstOrDefaultAsync(x=>x.Id==id,ct);public Task AddFileAsync(StorageFile x,CancellationToken ct)=>db.StorageFiles.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<FileTag>>TagsAsync(Guid id,CancellationToken ct)=>await db.FileTags.AsNoTracking().Where(x=>x.StorageFileId==id).ToListAsync(ct);public Task AddTagAsync(FileTag x,CancellationToken ct)=>db.FileTags.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<StorageFolder>>FoldersAsync(Guid o,bool trash,CancellationToken ct)=>await db.StorageFolders.IgnoreQueryFilters().AsNoTracking().Where(x=>x.OrganizationId==o&&x.IsDeleted==trash).OrderBy(x=>x.Name).ToListAsync(ct);public Task<StorageFolder?>FolderAsync(Guid id,bool deleted,CancellationToken ct)=>deleted?db.StorageFolders.IgnoreQueryFilters().FirstOrDefaultAsync(x=>x.Id==id,ct):db.StorageFolders.FirstOrDefaultAsync(x=>x.Id==id,ct);public Task AddFolderAsync(StorageFolder x,CancellationToken ct)=>db.StorageFolders.AddAsync(x,ct).AsTask();public Task<bool>FolderNameExistsAsync(Guid o,Guid?p,string n,Guid?e,CancellationToken ct)=>db.StorageFolders.AnyAsync(x=>x.OrganizationId==o&&x.ParentFolderId==p&&x.Name==n&&(!e.HasValue||x.Id!=e),ct);public Task<bool>HasChildrenAsync(Guid id,CancellationToken ct)=>db.StorageFolders.AnyAsync(x=>x.ParentFolderId==id,ct);public Task<bool>ChecksumExistsAsync(Guid o,string c,CancellationToken ct)=>db.StorageFiles.AnyAsync(x=>x.OrganizationId==o&&x.Checksum==c,ct);public async Task<(long Count,long Size)>FileTotalsAsync(Guid o,CancellationToken ct){var q=db.StorageFiles.Where(x=>x.OrganizationId==o);return(await q.LongCountAsync(ct),await q.SumAsync(x=>(long?)x.Size,ct)??0);}public async Task<IReadOnlyList<(string Category,long Size)>>CategoryTotalsAsync(Guid o,CancellationToken ct)=>await db.StorageFiles.Where(x=>x.OrganizationId==o).GroupBy(x=>x.Category.Name).Select(x=>new ValueTuple<string,long>(x.Key,x.Sum(y=>y.Size))).ToListAsync(ct);}
